define('common/tools/ruler',['require','underscore','underscoreDeepExtend','./draggable','text!./ruler.html','less!./ruler'],function (require) {

	'use strict';

	var _ = require('underscore');

	// DEEP EXTEND...you may need to add this line in your sim's config if you are trying to use this:
	// underscoreDeepExtend: '../../bower_components/underscore-deep-extend/index',
	var underscoreDeepExtend = require('underscoreDeepExtend');
	_.mixin({deepExtend: underscoreDeepExtend(_)});

	var Draggable = require('./draggable');

	var html  = require('text!./ruler.html');

	require('less!./ruler');

	var dx,
		dy,
		translate;

	var RulerView = Draggable.extend({

		template: _.template(html),

		tagName: 'div',
		className: 'ruler-view',

		events: {
			'mousedown' : 'panelDown',
			'touchstart': 'panelDown'
		},

		initialize: function(options) {
			options = _.deepExtend({
				position: {
					x: 30,
					y: 30
				},
				captureOnBody: false,
				mouseLeaveCancels: true,

				units : 'cm',
				pxPerUnit : 5,
				orientation : 'vertical',
				rulerWidth: 10,
				rulerMeasureUnits : 100,
				ticks : [{
					type: 'full',
					at : 10
				},{
					type: 'mid',
					at : 5
				},{
					type: 'unit',
					at : 1
				}]
			}, options);

			Draggable.prototype.initialize.apply(this, [options]);

			this.position = options.position;
			this.orientation = options.orientation;
			this.pxPerUnit = options.pxPerUnit;
			this.rulerWidth = options.rulerWidth;
			this.units = options.units;
			this.rulerMeasureUnits = options.rulerMeasureUnits;

			// sort ticks from greatest to least
			this.ticks = _.sortBy(options.ticks, function(tick){
				return -1 * tick.at;
			});
		},

		render: function() {
			this.renderViewModel();
			this.renderRuler();
			this.bindDragEvents();
			this.resize();
			this.update();
		},


		renderViewModel: function(){

			this.viewModel = {
				orientation : this.orientation
			};

			this.makeTicks();
			this.makeCSS();
		},

		renderRuler: function() {

			this.$el.html(this.template(this.viewModel));
			this.$el.css(this.viewModel.viewCSS);

			_(this.viewModel.css).each(function(css){
				this.$el.find(css.selector).css(css.rule);
			}, this);
		},

		/**
		 * make an array of label and tick types
		 */
		makeTicks: function(){

			this.viewModel.ticks = [];

			// counting by one up to the full ruler length...
			for (var iter = 1; iter < this.rulerMeasureUnits; iter++){

				// find out the kind of tick that is at this iteration
				var tickIter = _.find(this.ticks, function(tick){
					return !(iter % tick.at);
				});

				// if a tick type does not make, go on to the next iteration
				// without adding a tick for this iteration
				if (_.isUndefined(tickIter)){
					continue;
				}

				// add the new tick type and value
				this.viewModel.ticks.push({
					at : iter,
					type: tickIter.type
				});
			}

			// modify the last "full" tick to include the unit label
			_.last(_.where(this.viewModel.ticks, {type : this.ticks[0].type})).at += ' ' + this.units;
		},

		/**
		 * Adjust css on view model for property dependent visual details
		 */
		makeCSS: function(){

			this.viewModel.viewCSS = {};

			this.viewModel.css = [{
				// ensures proper width of tick.
				// Font-size is crucial -- set to full "width" of ruler so that child elements
				// such as label and ticks will all be set proportionally by "ems" in css.
				selector : '.tick',
				rule : {
					width: this.pxPerUnit + 'px',
					fontSize : this.rulerWidth * this.pxPerUnit + 'px'
				}
			}];

			// tricky css stuff for when the ruler is vertical
			if (this.orientation === 'vertical') {
				this.viewModel.viewCSS = {
					width : this.rulerWidth * this.pxPerUnit + 'px',
					height: (this.rulerMeasureUnits * this.pxPerUnit + 2) + 'px'
				};
				this.viewModel.css.push({
					selector : '.ruler',
					rule : {
						marginTop : -1 * this.rulerWidth * this.pxPerUnit + 'px',
						width: (this.rulerMeasureUnits * this.pxPerUnit + 2) + 'px',
						height: this.rulerWidth * this.pxPerUnit + 'px',
					}
				});
			}
			else if (this.orientation === 'horizontal') {
				this.viewModel.viewCSS = {
					height: this.rulerWidth * this.pxPerUnit + 'px',
					width: (this.rulerMeasureUnits * this.pxPerUnit + 2) + 'px'
				};
				this.viewModel.css.push({
					selector: '.ruler',
					rule: {
						width: (this.rulerMeasureUnits * this.pxPerUnit + 2) + 'px',
						height: this.rulerWidth * this.pxPerUnit + 'px',
					}
				});
			}
		},

		panelDown: function(event) {
			if (event.currentTarget === this.el) {
				event.preventDefault();

				this.$el.addClass('dragging');

				this.dragging = true;

				this.fixTouchEvents(event);

				this.dragX = event.pageX;
				this.dragY = event.pageY;
			}
		},

		drag: function(event) {
			if (this.dragging) {

				this.fixTouchEvents(event);

				dx = event.pageX - this.dragX;
				dy = event.pageY - this.dragY;

				if (!this.boxOutOfBounds(this.position.x + dx, this.position.y + dy)) {

					this.position.x += dx;
					this.position.y += dy;
				}

				this.dragX = event.pageX;
				this.dragY = event.pageY;

				this.updateOnNextFrame = true;
			}
		},

		dragEnd: function(event) {
			if (this.dragging) {
				this.dragging = false;
				this.$el.removeClass('dragging');
			}
		},

		setPosition: function(x, y) {
			this.position.x = x;
			this.position.y = y;
			this.updateOnNextFrame = true;
		},

		update: function(time, delta, paused, timeScale) {

			// If there aren't any changes, don't do anything.
			if (!this.updateOnNextFrame)
				return;

			this.updateOnNextFrame = false;

			translate = 'translateX(' + this.position.x + 'px) translateY(' + this.position.y + 'px)';

			this.$el.css({
				'-webkit-transform': translate,
				'-ms-transform': translate,
				'-o-transform': translate,
				'transform': translate,
			});
		}
	});

	return RulerView;
});


define('text!common/bar-graph/bar-graph.html',[],function () { return '<div class="bar-graph">\r\n    <h4 class="title"><%= title%></h4>\r\n    <ul class="bars">\r\n        <% _.each(bars, function(bar){ %>\r\n            <li class="attribute <%= bar.class %>" id="<%= bar.linkTo %>"><label><%= bar.label %></label><% if(bar.class !== \'total\'){%><div class="bar <%= bar.linkTo %>"></div><% };%></li>\r\n        <% }); %>\r\n    </ul>\r\n    <div class="total-marker"><p><%= totalLabel %></p></div>\r\n</div>';});


define('less/less!common/bar-graph/bar-graph',[],function(){});
define('constants',['require','underscore'],function (require) {

    'use strict';


    var _ = require('underscore');

    var Constants = {};
    var ColorConstants = {
        'cool-gray' : '#6a7686',
        'dark-gray' : '#2d3239',
        'light-gray': '#939daa',
        'pale-orange': '#ef9152',
        'sky-blue'  : '#52b0ef',
        'pale-green': '#7a9d8c',
        'navy-blue' : '#21366b',
        'pale-red'  : '#e15454',
        'pale-blue' : '#549be1',
        'pale-aqua' : '#54e19b'
    };


    Constants.ColorConstants = ColorConstants;

    /*************************************************************************
     **                                                                     **
     **                         UNIVERSAL CONSTANTS                         **
     **                                                                     **
     *************************************************************************/

    Constants.GRAVITATIONAL_ACCELERATION = 9.8; // m/s^2



    /*************************************************************************
     **                                                                     **
     **                           SCENE CONSTANTS                           **
     **                                                                     **
     *************************************************************************/

     var Scene = {};
     Scene.DTT = 0.01;  //target time increment in seconds (independent of frame rate)
     Scene.RATE = 1;    //overall time rate: 1 = normal, 0.5 = halfspeed, 0.25 = quarter speed
     Scene.PX_PER_METER = 500;  //scale factor f=500  pixels per meter
     Scene.FPS = 20;    //frames per second of movie
     Scene.FDT = 1/Scene.FPS;   //time increment for free-falling mass
     Scene.SOUNDS_ENABLED = 'high';   //true if sounds enabled; allows user to turn off sounds

     Scene.SHELF_FROM_TOP = 0.95;

     Constants.Scene = Scene;


    /*************************************************************************
     **                                                                     **
     **                        SIM SETTINGS CONSTANTS                       **
     **                                                                     **
     *************************************************************************/
    var SimSettings = {};
    SimSettings.SPEED = [{
            label : '1/16 time',
            value : 0.0625
        }, {
            label : '1/4 time',
            value : 0.25
        }, {
            label : 'Normal',
            value : 1,
            isDefault : true
    }];

    SimSettings.GRAVITY = [{
            label: 'Jupiter',
            value : 2.64 * Constants.GRAVITATIONAL_ACCELERATION
        },{
            label: 'Moon',
            value : Constants.GRAVITATIONAL_ACCELERATION / 6
        },{
            label: 'Earth',
            value : Constants.GRAVITATIONAL_ACCELERATION,
            isDefault : true,
        },{
            label: 'Planet X',
            value : 0.38 * Constants.GRAVITATIONAL_ACCELERATION
        },{
            label: 'g = 0',
            value : 0,
    }];
    SimSettings.GRAVITY_DEFAULT = _.find(SimSettings.GRAVITY, {isDefault: true}).value;

    SimSettings.FRICTION_STEPS = 11;
    SimSettings.FRICTION_EQUATION = function(step){
        return (0.1*Math.pow(1.5, step)) - 0.1;
    };
    SimSettings.FRICTION_STEP_DEFAULT = 5;
    SimSettings.FRICTION_DEFAULT = SimSettings.FRICTION_EQUATION(SimSettings.FRICTION_STEP_DEFAULT);

    SimSettings.LENGTH_STEP = 0.1;
    SimSettings.LENGTH_MIN = 0.5;
    SimSettings.LENGTH_MAX = 2.5;
    SimSettings.DEFAULT_LENGTH = 2;

    SimSettings.MASS_STEP = 0.1;
    SimSettings.MASS_MIN = 0.1;
    SimSettings.MASS_MAX = 2.1;
    SimSettings.DEFAULT_MASS = 1;

    Constants.SimSettings = SimSettings;



    /*************************************************************************
     **                                                                     **
     **                       SIM SYSTEM EQUATIONS                          **
     **                                                                     **
     *************************************************************************/

    var SystemEquations = {};
    SystemEquations.PERIOD = function(mass, springStiffness){
        return 2 * Math.PI * Math.sqrt(mass/springStiffness);
    };
    SystemEquations.KINETIC_ENERGY = function(mass, velocity){
        return 0.5 * mass * velocity * velocity;
    };
    SystemEquations.ELASTIC_POTENTIAL_ENERGY = function(stiffness, deltaY){
        return 0.5 * stiffness * deltaY * deltaY;
    };
    SystemEquations.GRAVITATIONAL_POTENTIAL_ENERGY = function(mass, gravity, yPosOfMass){
        return mass * gravity * yPosOfMass;
    };
    SystemEquations.DELTA_THERMAL = function(deltaDeltaY, mass, frictionConstant, velocity2){
        return deltaDeltaY * mass * frictionConstant * velocity2;
    };
    SystemEquations.TOTAL_ENERGY = function(kinetic, elasticPotential, gravitationalPotential, thermal){
        return kinetic + elasticPotential + gravitationalPotential + thermal;
    };


    SystemEquations.ACCELERATION = function(gravity, stiffness, mass, deltaY, frictionConstant, velocity){
        return gravity - (stiffness / mass) * deltaY - frictionConstant * velocity;
    };
    SystemEquations.VELOCITY2 = function(velocity, acceleration, time){
        return velocity + acceleration * time;
    };
    SystemEquations.DISPLACEMENT = function(velocity, time, acceleration){
        return velocity * time + 0.5 * acceleration * time * time;
    };


    Constants.SystemEquations = SystemEquations;



    /*************************************************************************
     **                                                                     **
     **                       SIM DEFAULT MODEL VALUES                      **
     **                                                                     **
     *************************************************************************/

    var SpringDefaults = {};
    SpringDefaults.REST_L = 0.3;
    SpringDefaults.STIFFNESS = SimSettings.SOFTNESS_DEFAULT;

    // Appearance related
    SpringDefaults.PEG_COLOR = ColorConstants['navy-blue'];
    SpringDefaults.COLOR = ColorConstants['cool-gray'];
    SpringDefaults.COILS = 11;
    SpringDefaults.WIDTH = 0.10;

    SpringDefaults.RING_RADIUS = 0.02;
    SpringDefaults.K_TO_THICKNESS = function(k){
        return 2 + 0.03 * k;
    };


    Constants.SpringDefaults = SpringDefaults;


    var BodyDefaults = {};
    // TODO convert from px to meters
    BodyDefaults.WIDTH_TO_HOOK_RADIUS = function(width){
        return (9 + 0.1 * width)/Scene.PX_PER_METER;
    };
    BodyDefaults.MASS_TO_HEIGHT = function(mass){
        return (30 + 240 * mass)/Scene.PX_PER_METER;
    };
    BodyDefaults.MASS_TO_WIDTH = function(mass){
        return (30 + 160 * mass)/Scene.PX_PER_METER;
    };

    BodyDefaults.COLOR = ColorConstants['light-gray'];

    Constants.BodyDefaults = BodyDefaults;


    return Constants;
});


define('common/bar-graph/bar-graph',['require','underscore','backbone','text!./bar-graph.html','less!./bar-graph','constants'],function(require) {

    'use strict';

    var _        = require('underscore');
    var Backbone = require('backbone');

    var html = require('text!./bar-graph.html');

    require('less!./bar-graph')

    var Constants = require('constants');

    /**
     * A view that represents a movable target model
     */
    var BarGraphView = Backbone.View.extend({

        template : _.template(html),

        tagName : 'div',
        className : 'bar-graph-view',

        initialize: function(options) {
            options = _.extend({
                title: '',
                totalLabel : 'Total E',
                maxValue : 6, // can calculate this later
                graphHeight: 440,
                zoom: 1
            }, options);

            this.title = options.title;
            this.totalLabel = options.totalLabel;
            this.maxValue = options.maxValue;
            this.graphHeight = options.graphHeight;
            this._zoom = options.zoom;

            this.listenTo(this.model, 'change:bar', this.updateBar);
        },

        render: function(){
            var data = {
                title : this.title,
                totalLabel : this.totalLabel,
                bars : this.model.get('bars'),
                zoom : this._zoom
            };

            this.$el.html(this.template(data));

            this.initBars();
            this.resize();
        },

        initBars: function() {
            var width = 100 / this.model.get('bars').length + '%';

            this.$barGraph = this.$el.find('.bar-graph');
            this.$title = this.$barGraph.find('.title');
            this.$totalMarker = this.$barGraph.find('.total-marker');
            this.$attribute = this.$barGraph.find('.attribute');
            this.$total = this.$barGraph.find('.total');

            this.$attribute.css({
                width: width
            });

            _.each(this.model.get('bars'), function(bar, iter){
                var $bar;

                if(bar.class === 'total'){
                    return;
                }

                $bar = $('<div class="bar ' + bar.linkTo + '"></div>');
                $bar.css({
                    zIndex: iter
                });
                this.$total.append($bar);
            }, this);

            this.$total.find('.bar').wrapAll('<div class="bar-wrapper"/>');

            this.$bar = this.$barGraph.find('.bar');
        },

        updateBar: function(bar){
            this.$el.find('.' + bar.linkTo).css({
                maxHeight: bar.value/this.maxValue + 'em'
            });

            if(bar.class === 'total'){
                this.$el.find('.total-marker').css({
                    bottom: bar.value/this.maxValue + 'em'
                });
            }
        },

        zoomIn: function(){
            this._zoom = Math.round(this._zoom);
            this._zoom ++;
            this.zoom();
        },

        zoomOut: function(){

            if(this._zoom < 0.25){
                return;
            }

            if(this._zoom <= 1){
                this._zoom = this._zoom * 0.5;
            }else{
                this._zoom --;
            }

            this.zoom();
        },

        zoom: function(){
            var zoomSize = this._zoom * this.graphHeight;

            this.$bar.add(this.$totalMarker).css({
                fontSize: zoomSize + 'px'
            });
        },

        resize: function(){
            this.$title.css({
                width: this.graphHeight + 'px'
            });

            this.$barGraph.add(this.$bars).add(this.$attribute).css({
                height: this.graphHeight + 'px'
            });

            this.$bar.css({
                height: (10 * this.graphHeight)+ 'px'
            });

            this.zoom();
        }

    });

    return BarGraphView;
});

